{"implementation":"def solve(case):
    import math

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "core_distance" not in case or "distances" not in case:
        raise ValueError("missing required field")

    nodes = case["nodes"]
    core = case["core_distance"]
    distances = case["distances"]

    if not isinstance(nodes, list) or not isinstance(core, dict) or not isinstance(distances, list):
        raise ValueError("invalid field type")
    if any(not isinstance(node, str) for node in nodes):
        raise ValueError("node identifiers must be strings")
    if len(set(nodes)) != len(nodes):
        raise ValueError("duplicate node identifier")

    def valid_number(value):
        return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)

    for node in nodes:
        if node not in core or not valid_number(core[node]) or core[node] < 0:
            raise ValueError("invalid core distance")

    node_set = set(nodes)
    edges = {}
    for entry in distances:
        if not isinstance(entry, list) or len(entry) != 3:
            raise ValueError("invalid distance entry")
        left, right, distance = entry
        if not isinstance(left, str) or not isinstance(right, str):
            raise ValueError("invalid endpoint")
        if left not in node_set or right not in node_set or left == right:
            raise ValueError("invalid endpoint")
        if not valid_number(distance) or distance < 0:
            raise ValueError("invalid distance")
        endpoints = tuple(sorted((left, right)))
        if endpoints in edges:
            raise ValueError("duplicate undirected edge")
        edges[endpoints] = max(core[left], core[right], distance)

    ordered = sorted((weight, left, right) for (left, right), weight in edges.items())
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    def union(left, right):
        left_root = find(left)
        right_root = find(right)
        if left_root == right_root:
            return False
        if rank[left_root] < rank[right_root]:
            left_root, right_root = right_root, left_root
        parent[right_root] = left_root
        if rank[left_root] == rank[right_root]:
            rank[left_root] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    for weight, left, right in ordered:
        if union(left, right):
            mst_edges.append([left, right, weight])
            total_weight += weight
            if len(mst_edges) == max(0, len(nodes) - 1):
                break

    if len(mst_edges) != max(0, len(nodes) - 1):
        raise ValueError("disconnected graph")
    return {"mst_edges": mst_edges, "total_weight": total_weight}"}
